  const w2y = Math.cos((y+w1y)*0.014-t*0.17)*8 + Math.sin((x+w1x)*0.011+t*0.2)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.5)*110, 80+Math.cos(t*0.35)*55, 0.07, 2.2, 0.8],
    [320+Math.cos(t*0.45)*110, 160+Math.sin(t*0.6)*55, 0.09, 1.8, 1.2],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.42+1)*95, 0.055, 2.5, 0.6],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.55+3)*65, 0.11, 1.6, 1.4],
    [380+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.8+2)*75, 0.065, 2.8, 0.9],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.48)*85, 0.085, 2.0, 1.1],
    [60+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.5+5)*50, 0.1, 1.4, 1.3],
    [420+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.65+4)*55, 0.075, 2.3, 0.7]
  ];
  let aS=0, iS=0, cross=0, harm=0;
  for (let i=0; i<src.length; i++) {
    const [sX,sY,f,sp,h] = src[i];
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w = Math.sin(d*f-t*sp);
    const w2 = Math.sin(d*f*0.6+t*sp*0.5+1.8);
    aS += w; iS += w2; cross += w*w2*h; harm += Math.sin(d*f*0.3-t*sp*0.2+i*0.8)*h;
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, cr = cross/n, hm = harm/n;
  const bg1 = Math.sin(sx*0.035+sy*0.022+t*0.7);
  const bg2 = Math.sin(sx*0.028-sy*0.038+t*1.0);
  const bg3 = Math.sin((sx+sy)*0.1+t*2.2)*0.3;
  const bg4 = Math.sin((sx-sy)*0.08-t*1.8)*0.3;
  const bg = (bg1+bg2)/2+bg3+bg4;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.4);
  const sp2 = Math.sin(dist*0.035+ang*4.5-t*1.1);
  const sp3 = Math.sin(dist*0.025-ang*2-t*0.8)*0.5;
  const spiral = (sp1+sp2)*0.35+sp3;
  const fb = Math.sin(act*2.5+t)*0.3;
  const rd = Math.tanh((act - inh*0.65 + cr*0.4 + hm*0.3 + bg*0.25 + spiral*0.35 + fb)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.13)*Math.sin(sy*0.13)+Math.sin((sx+sy)*0.09+t*0.8)*0.4+Math.sin((sx-sy)*0.11-t*1.2)*0.3)*1.4)*0.25;
  const micro = Math.sin(sx*0.25+t*3)*Math.sin(sy*0.25-t*2.5)*0.08;
  const blend = rd*0.65+cell*0.25+micro;
