  const pal = [
    [6,12,52],[12,35,85],[18,65,115],[25,110,130],
    [45,155,140],[120,185,130],[195,195,95],
    [225,175,70],[220,130,65],[195,80,60],
    [155,45,55],[95,25,55],[50,15,48],[6,12,52]
